-- Imaging clock placement, step 2 of 2: clock positions, updated in place.
-- GENERATED by thebolt/proposals/2026-10-29-gen-imaging-migration.mjs. Do not hand-edit.
--
-- 33 imaging positions take a new category and fallback; 59 positions take a new
-- sort_order, because fillers move off imaging breaks (a filler never splits imaging from
-- its record). All 298 positions are matched by clock name + today's sort_order and guarded
-- by the type and category they hold today (the d0e0039 seed, verified live 2026-10-29).
-- Every position keeps its id, so approved logs keep clock_position_id and TOH timing.
-- Logs already generated keep the songs they picked; logs generated after this use the
-- new clocks.
--
-- Aborts, changing nothing, if any guard misses (the clocks drifted), if step 1 has not
-- run, or if a category the clocks now call has no songs yet.

BEGIN;

DO $$
DECLARE n int;
BEGIN
  -- Each newly called category needs songs: fallback is one step, and Power, Discovery
  -- and Recurrent Sweepers fall back to Front-sell, itself new.
  SELECT count(*) INTO n FROM categories c WHERE c.station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3'
    AND c.name IN ('Back-sell', 'Discovery Sweepers', 'Front-sell', 'Gold 00s', 'Gold 10s', 'Gold 90s', 'New Music Back', 'Power', 'Recurrent Sweepers', 'Station Promos')
    AND EXISTS (SELECT 1 FROM song_categories sc WHERE sc.category_id = c.id);
  IF n <> 10 THEN RAISE EXCEPTION 'only % of 10 newly called categories have songs: run step 1 and file the renders (Music > Inbox) first', n; END IF;
END $$;

CREATE TEMP TABLE clock_update (clock text, sort_order int, position_type text, from_cat text,
  new_sort_order int, to_cat text, fallback text, recat boolean) ON COMMIT DROP;

CREATE TEMP TABLE clock_update_ids ON COMMIT DROP AS
  SELECT p.id, u.* FROM clock_update u
    JOIN clocks k ON k.station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND k.name = u.clock
    JOIN clock_positions p ON p.clock_id = k.id AND p.sort_order = u.sort_order AND p.position_type = u.position_type
    JOIN categories c ON c.id = p.category_id AND c.name = u.from_cat;

DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM clock_update_ids;
  IF n <> 298 THEN RAISE EXCEPTION 'only % of 298 positions are where and what this migration expects: the clocks have drifted, regenerate', n; END IF;
  SELECT count(*) INTO n FROM clock_positions p JOIN clocks k ON k.id = p.clock_id WHERE k.station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3';
  IF n <> 298 THEN RAISE EXCEPTION 'expected 298 clock positions, got %', n; END IF;
END $$;

UPDATE clock_positions p SET sort_order = u.new_sort_order
FROM clock_update_ids u WHERE p.id = u.id AND p.sort_order <> u.new_sort_order;

UPDATE clock_positions p SET
  category_id = nc.id,
  constraints = CASE WHEN fc.id IS NULL THEN coalesce(p.constraints, '{}'::jsonb) - 'fallbackCategoryId'
    ELSE coalesce(p.constraints, '{}'::jsonb) || jsonb_build_object('fallbackCategoryId', fc.id::text) END
FROM clock_update_ids u
  JOIN categories nc ON nc.station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND nc.name = u.to_cat
  LEFT JOIN categories fc ON fc.station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND fc.name = u.fallback
WHERE p.id = u.id AND u.recat;

DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM clock_update_ids u
    JOIN clock_positions p ON p.id = u.id AND p.sort_order = u.new_sort_order
    JOIN categories c ON c.id = p.category_id AND c.name = u.to_cat
    LEFT JOIN categories fc ON fc.station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND fc.name = u.fallback
    WHERE NOT u.recat OR (p.constraints->>'fallbackCategoryId') IS NOT DISTINCT FROM fc.id::text;
  IF n <> 298 THEN RAISE EXCEPTION 'expected 298 positions in their new place, got %', n; END IF;
  SELECT count(*) INTO n FROM (SELECT clock_id, sort_order FROM clock_positions GROUP BY 1, 2 HAVING count(*) > 1) d;
  IF n > 0 THEN RAISE EXCEPTION '% duplicate clock slots after the update', n; END IF;
END $$;

COMMIT;
